const ElegantAiBrainIcon = ({ className = "w-5 h-5", ...props }: React.SVGProps<SVGSVGElement>) => {
  return (
    <svg
      viewBox="0 0 100 100"
      className={className}
      fill="none"
      {...props}
    >
      <style>{`
        @keyframes ai-spin-cw {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
        @keyframes ai-spin-ccw {
          from { transform: rotate(360deg); }
          to { transform: rotate(0deg); }
        }
        @keyframes ai-flow {
          to { stroke-dashoffset: -20; }
        }
        @keyframes ai-pulse-glow {
          0%, 100% { opacity: 0.35; transform: scale(0.95); }
          50% { opacity: 0.9; transform: scale(1.05); }
        }
        @keyframes ai-node-blink {
          0%, 100% { opacity: 0.5; r: 1.5; }
          50% { opacity: 1; r: 2.8; }
        }
        @keyframes ai-core-breathe {
          0%, 100% { transform: scale(0.96); filter: drop-shadow(0 0 2px rgba(235, 141, 112, 0.25)); }
          50% { transform: scale(1.04); filter: drop-shadow(0 0 8px rgba(235, 141, 112, 0.6)); }
        }
        .ai-rot-cw {
          transform-origin: 50px 50px;
          animation: ai-spin-cw 12s linear infinite;
        }
        .ai-rot-ccw {
          transform-origin: 50px 50px;
          animation: ai-spin-ccw 8s linear infinite;
        }
        .ai-pulse-element {
          transform-origin: 50px 50px;
          animation: ai-pulse-glow 3s ease-in-out infinite;
        }
        .ai-core-el {
          transform-origin: 50px 50px;
          animation: ai-core-breathe 4s ease-in-out infinite;
        }
        .ai-line-flow {
          stroke-dasharray: 6 4;
          animation: ai-flow 1.5s linear infinite;
        }
        .ai-node {
          animation: ai-node-blink 2s ease-in-out infinite;
        }
        .ai-node-delayed {
          animation: ai-node-blink 2s ease-in-out infinite;
          animation-delay: 1s;
        }
      `}</style>

      <defs>
        {/* Fit Colors: Combining Peach (#eb8d70), Coral (#f43f5e), Pink (#ec4899), Indigo (#6366f1) */}
        <linearGradient id="ai-grad-primary" x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="#eb8d70" />
          <stop offset="50%" stopColor="#ec4899" />
          <stop offset="100%" stopColor="#a855f7" />
        </linearGradient>
        <linearGradient id="ai-grad-secondary" x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="#a855f7" />
          <stop offset="100%" stopColor="#3b82f6" />
        </linearGradient>
        <radialGradient id="ai-radial-glow" cx="50%" cy="50%" r="50%">
          <stop offset="0%" stopColor="#eb8d70" stopOpacity="0.25" />
          <stop offset="100%" stopColor="#3b82f6" stopOpacity="0" />
        </radialGradient>
      </defs>

      {/* Ambient background glow */}
      <circle cx="50" cy="50" r="45" fill="url(#ai-radial-glow)" className="ai-pulse-element" />

      {/* Futuristic Orbit Ring 1 (Outer - Clockwise) */}
      <circle
        cx="50"
        cy="50"
        r="44"
        stroke="url(#ai-grad-secondary)"
        strokeWidth="1"
        strokeDasharray="4 8 16 8"
        className="ai-rot-cw opacity-40"
      />

      {/* Futuristic Orbit Ring 2 (Inner - Counter Clockwise) */}
      <circle
        cx="50"
        cy="50"
        r="39"
        stroke="url(#ai-grad-primary)"
        strokeWidth="1.5"
        strokeDasharray="12 6 3 6"
        className="ai-rot-ccw opacity-60"
      />

      {/* Glowing Outer Nodes on orbits */}
      <g className="ai-rot-cw">
        <circle cx="50" cy="6" r="3" fill="#eb8d70" className="ai-node" />
        <circle cx="94" cy="50" r="2.5" fill="#ec4899" />
      </g>
      <g className="ai-rot-ccw">
        <circle cx="50" cy="94" r="3" fill="#3b82f6" className="ai-node-delayed" />
        <circle cx="6" cy="50" r="2.5" fill="#a855f7" />
      </g>

      {/* Central AI Brain/Chip Core */}
      <g className="ai-core-el">
        {/* Beautiful Left Brain Hemisphere with flowing currents */}
        <path
          d="M 50,22 C 34,22 22,30 22,46 C 22,54 26,58 24,64 C 20,72 28,80 40,80 C 44,80 46,78 50,78"
          stroke="url(#ai-grad-primary)"
          strokeWidth="3.5"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        {/* Moving signal streams inside the left hemisphere */}
        <path
          d="M 32,36 C 26,42 32,48 38,46"
          stroke="url(#ai-grad-primary)"
          strokeWidth="1.5"
          strokeLinecap="round"
          className="ai-line-flow opacity-85"
        />
        <path
          d="M 26,52 C 32,54 34,60 42,58"
          stroke="url(#ai-grad-primary)"
          strokeWidth="1.5"
          strokeLinecap="round"
          className="ai-line-flow opacity-85"
        />

        {/* Beautiful Right Brain Hemisphere - Digital Circuit Tracks with Blinking Nodes */}
        {/* Outer track */}
        <path
          d="M 50,22 C 66,22 78,30 78,46 L 72,46"
          stroke="url(#ai-grad-secondary)"
          strokeWidth="3.5"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        <circle cx="70" cy="46" r="2.5" fill="#3b82f6" className="ai-node" />

        {/* Top Circuit Path */}
        <path
          d="M 50,32 L 64,32 L 68,36 L 74,36"
          stroke="url(#ai-grad-secondary)"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          className="ai-line-flow"
        />
        <circle cx="74" cy="36" r="2" fill="#a855f7" className="ai-node-delayed" />

        {/* Mid Circuit Path */}
        <path
          d="M 50,50 L 62,50 L 66,54 L 76,54"
          stroke="url(#ai-grad-secondary)"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          className="ai-line-flow"
        />
        <circle cx="76" cy="54" r="2" fill="#3b82f6" className="ai-node" />

        {/* Lower Circuit Path */}
        <path
          d="M 50,62 L 60,62 L 64,66 L 70,66"
          stroke="url(#ai-grad-secondary)"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        <circle cx="70" cy="66" r="2" fill="#3b82f6" className="ai-node-delayed" />

        {/* Lower track */}
        <path
          d="M 50,78 C 62,78 70,74 72,66 L 68,66"
          stroke="url(#ai-grad-secondary)"
          strokeWidth="3.5"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        <circle cx="67" cy="66" r="2" fill="#3b82f6" />
      </g>

      {/* Central Division bar */}
      <line
        x1="50"
        y1="20"
        x2="50"
        y2="80"
        stroke="#ffffff"
        strokeWidth="1.5"
        strokeDasharray="2 3"
        className="opacity-45"
      />
    </svg>
  );
};


const HintTooltip = ({ text, currentSlideColor = "#6366f1", showHints = false }: { text: string; currentSlideColor?: string; showHints?: boolean }) => {
  if (!showHints) return null;
  return (
    <span className="relative group/tooltip inline-flex items-center justify-center cursor-help ml-1.5 align-middle select-none shrink-0">
      <svg
        className="w-3.5 h-3.5 text-slate-400 hover:text-rose-500 transition-colors"
        fill="none"
        stroke="currentColor"
        strokeWidth="2.5"
        viewBox="0 0 24 24"
      >
        <circle cx="12" cy="12" r="10" />
        <path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3" />
        <line x1="12" y1="17" x2="12.01" y2="17" />
      </svg>
      <span 
        className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 w-56 scale-0 group-hover/tooltip:scale-100 transition-all duration-200 origin-bottom p-2.5 rounded-xl shadow-xl pointer-events-none leading-relaxed z-[9999] text-[11px] font-medium text-white text-center font-sans normal-case block"
        style={{ backgroundColor: currentSlideColor }}
      >
        {text}
        <span 
          className="absolute top-full left-1/2 -translate-x-1/2 border-4 border-transparent"
          style={{ borderTopColor: currentSlideColor }}
        />
      </span>
    </span>
  );
};

