const getTemplateStyle = (templateId: string) => {
  switch (templateId) {
    case "sahara_gold":
      return { background: "linear-gradient(135deg, #f59e0b 0%, #ea580c 50%, #7c2d12 100%)" };
    case "casbah_minimal":
      return { background: "linear-gradient(135deg, #475569 0%, #1e293b 100%)" };
    case "berber_indigo":
      return { background: "linear-gradient(135deg, #4f46e5 0%, #312e81 100%)" };
    case "turquoise_sea":
      return { background: "linear-gradient(135deg, #0d9488 0%, #0891b2 50%, #0369a1 100%)" };
    case "moorish_emerald":
      return { background: "linear-gradient(135deg, #064e3b 0%, #022c22 100%)" };
    case "sunset_rose":
      return { background: "linear-gradient(135deg, #f43f5e 0%, #e11d48 50%, #9f1239 100%)" };
    case "cyber_kasbah":
      return { background: "linear-gradient(135deg, #a855f7 0%, #701a75 50%, #4c1d95 100%)" };
    case "slate_noir":
      return { background: "linear-gradient(135deg, #1c1917 0%, #0c0a09 100%)" };
    case "terracotta":
      return { background: "linear-gradient(135deg, #c2410c 0%, #9a3412 50%, #7c2d12 100%)" };
    case "velvet_crimson":
      return { background: "linear-gradient(135deg, #be123c 0%, #9f1239 50%, #4c0519 100%)" };
    default:
      return null;
  }
};

