export function MerchantProductPriceBadge({ 
  productId, 
  price,
  discountEnabled,
  discountPercent,
  customStyle
}: { 
  productId: string; 
  price: number;
  discountEnabled?: boolean;
  discountPercent?: number;
  customStyle?: React.CSSProperties;
}) {
  const flash = usePriceUpdateHighlight(productId);
  const baseStyle = !flash ? { backgroundColor: "#3b42f6" } : {};
  const mergedStyle = { ...baseStyle, ...customStyle };

  const isDiscountEnabled = !!discountEnabled;
  const pct = discountPercent !== undefined ? discountPercent : 15;
  const currentPrice = isDiscountEnabled
    ? Math.round(price * (1 - pct / 100))
    : price;

  return (
    <div 
      className={`absolute top-4 left-4 px-3.5 py-1.5 rounded-full shadow-md text-white font-extrabold text-[12.5px] tracking-wide transition-all duration-300 ${
        flash === "up" 
          ? "animate-price-flash-red bg-red-600 scale-105" 
          : flash === "down" 
          ? "animate-price-flash-green bg-emerald-600 scale-105" 
          : ""
      }`}
      style={mergedStyle}
    >
      {isDiscountEnabled ? (
        <div className="flex items-center gap-1">
          <span className="line-through opacity-60 text-[10px]">{price.toLocaleString()}</span>
          <span>{currentPrice.toLocaleString()} DZD</span>
        </div>
      ) : (
        <span>{price.toLocaleString()} DZD</span>
      )}
    </div>
  );
}

