  // Generate 30 days of data ending today
  const last30DaysData = React.useMemo(() => {
    const dataList = [];
    const today = new Date();
    
    // Filter orders matching this store's ID
    const activeStoreOrders = (orders || []).filter(o => o.storeId === myStore.id);
    
    for (let i = 29; i >= 0; i--) {
      const d = new Date(today);
      d.setDate(today.getDate() - i);
      
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, "0");
      const day = String(d.getDate()).padStart(2, "0");
      const dateKeyStr = `${year}-${month}-${day}`;
      
      // Label like "May 23"
      const dateLabel = d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
      
      // Deterministic smooth baseline curve utilizing sine wave patterns based on store's unique string hash
      const storeHash = (myStore.id || "store_1").split("").reduce((acc, char) => acc + char.charCodeAt(0), 0);
      const angle = ((i + storeHash % 10) * Math.PI) / 6.2; // roughly 12-day wave period
      const trend = 16000 + (storeHash % 4) * 6000 + Math.sin(angle) * 7500 + (30 - i) * 120;
      const baselineSales = Math.max(2500, Math.round(trend));
      const baselineOrders = Math.max(1, Math.round(trend / 6000 + Math.cos(angle) * 0.8));
      
      // Find orders matching this day
      let actualOrdersSales = 0;
      let actualOrdersCount = 0;
      
      activeStoreOrders.forEach(o => {
        if (o.date && o.date.startsWith(dateKeyStr)) {
          actualOrdersSales += (o.total || 0);
          actualOrdersCount += 1;
        }
      });
      
      const combinedSales = baselineSales + actualOrdersSales;
      const combinedOrders = baselineOrders + actualOrdersCount;
      
      dataList.push({
        dateLabel,
        dateKeyStr,
        "Baseline Sales": baselineSales,
        "Actual New Sales": actualOrdersSales,
        "Total Revenue": combinedSales,
        "Orders": combinedOrders,
      });
    }
    return dataList;
  }, [orders, myStore.id, myStore.name]);

  // 5-month seasonal performance categories graph data mimicking screenshot precisely
