  const validateWizardStep = (stepNum: number): boolean => {
    if (stepNum === 1) {
      if (!blankProductName || !blankProductName.trim()) return false;
      if (!blankProductSku || !blankProductSku.trim()) return false;
      if (!wizardProductStory || !wizardProductStory.trim()) return false;
    }
    if (stepNum === 2) {
      const hasImage = wizardImages.some(img => img && img.trim() !== "");
      if (!hasImage) return false;
    }
    if (stepNum === 3) {
      if (!blankProductCategory || !blankProductCategory.trim()) return false;
      const hasEmptySpecs = wizardProductSpecs.some(spec => !spec.key?.trim() || !spec.value?.trim());
      if (hasEmptySpecs) return false;
    }
    if (stepNum === 4) {
      if (!blankProductPrice || isNaN(blankProductPrice) || blankProductPrice <= 0) return false;
      if (wizardShippingCost === undefined || isNaN(wizardShippingCost) || wizardShippingCost < 0) return false;
      if (wizardStock === undefined || wizardStock === "" || isNaN(Number(wizardStock)) || Number(wizardStock) < 0 || !Number.isInteger(Number(wizardStock))) return false;
    }
    return true;
  };

  const handleImageUploadFiles = (files: FileList | null) => {
    if (!files || files.length === 0) return;
    if (!effectiveFeatureConfig.allowImageUploadDevice) {
      if (setMerchantFeedbackMessage) setMerchantFeedbackMessage("❌ Image upload from device is deactivated by platform configuration for your plan.");
      return;
    }
    const currentActiveImages = wizardImages.filter(img => img && img.trim() !== "");
    const filesToProcess = Array.from(files);
    let updatedAny = false;

    filesToProcess.forEach((file) => {
      if (file.type.startsWith("image/")) {
        const maxSizeBytes = effectiveFeatureConfig.maxImageSizeBytesMB * 1024 * 1024;
        if (file.size > maxSizeBytes) {
          if (setMerchantFeedbackMessage) setMerchantFeedbackMessage(`⚠️ Image ${file.name} exceeds maximum size limit of ${effectiveFeatureConfig.maxImageSizeBytesMB}MB.`);
          return;
        }
        const url = URL.createObjectURL(file);
        if (currentActiveImages.length < effectiveFeatureConfig.maxImages) {
          currentActiveImages.push(url);
          updatedAny = true;
        } else {
          if (setMerchantFeedbackMessage) setMerchantFeedbackMessage(`❌ Maximum limit of ${effectiveFeatureConfig.maxImages} images reached.`);
        }
      }
    });

    if (updatedAny) {
      setWizardImages(currentActiveImages);
      if (setMerchantFeedbackMessage) {
        setMerchantFeedbackMessage("✨ Local images loaded successfully! Verify in the live preview.");
      }
    }
  };

