  const handleAIOptimizeDescription = () => {
    if (!manualProductForm.name.trim()) {
      alert("Please specify a Product Item Name first so the AI can craft a custom sales pitch!");
      return;
    }

    setAiOptimizing(true);
    
    // Simulate active processing delay
    setTimeout(() => {
      const fullPitch = generateAIPitch(manualProductForm.name, manualProductForm.category);
      let currentLength = 0;
      setManualProductForm(prev => ({ ...prev, description: "" }));
      
      const interval = setInterval(() => {
        currentLength += Math.min(6, fullPitch.length - currentLength);
        if (currentLength >= fullPitch.length) {
          setManualProductForm(prev => ({ ...prev, description: fullPitch }));
          clearInterval(interval);
          setAiOptimizing(false);
        } else {
          setManualProductForm(prev => ({
            ...prev,
            description: fullPitch.substring(0, currentLength) + " ▌"
          }));
        }
      }, 15);
    }, 1200);
  };

  // Canvas Image Rendering Engine
  const drawCanvasImage = React.useCallback(() => {
    if (!canvasRef.current || !manualProductForm.imageUrl) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const img = new window.Image();
    img.crossOrigin = "anonymous";
    img.src = manualProductForm.imageUrl;
    img.onload = () => {
      // Set sizes based on crop standard
      if (canvasAspectRatio === "square") {
        canvas.width = 600;
        canvas.height = 600;
      } else {
        canvas.width = 800;
        canvas.height = 450;
      }

      // Center cropカバー fit
      const scale = Math.max(canvas.width / img.width, canvas.height / img.height);
      const x = (canvas.width - img.width * scale) / 2;
      const y = (canvas.height - img.height * scale) / 2;
      const w = img.width * scale;
      const h = img.height * scale;

      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Filters setup
      let filterStr = `brightness(${canvasFilterBrightness}%) contrast(${canvasFilterContrast}%) saturate(${canvasFilterSaturation}%)`;
      if (canvasImageEnhanced) {
        filterStr += ` contrast(112%) saturate(118%)`;
      }
      ctx.filter = filterStr;
      ctx.drawImage(img, x, y, w, h);

      // Apply real convolutional sharpening sharpen pass if requested
      if (canvasImageEnhanced) {
        try {
          const srcData = ctx.getImageData(0, 0, canvas.width, canvas.height);
          const src = srcData.data;
          const output = ctx.createImageData(canvas.width, canvas.height);
          const dst = output.data;
          const width = canvas.width;
          const height = canvas.height;
          // Weights for sharp high-pass
          const weights = [0, -0.2, 0, -0.2, 1.8, -0.2, 0, -0.2, 0];
          const side = Math.round(Math.sqrt(weights.length));
          const halfSide = Math.floor(side / 2);

          for (let cy = 0; cy < height; cy++) {
            for (let cx = 0; cx < width; cx++) {
              const dstOff = (cy * width + cx) * 4;
              let r = 0, g = 0, b = 0;
              for (let maskY = 0; maskY < side; maskY++) {
                for (let maskX = 0; maskX < side; maskX++) {
                  const pixelY = Math.min(height - 1, Math.max(0, cy + maskY - halfSide));
                  const pixelX = Math.min(width - 1, Math.max(0, cx + maskX - halfSide));
                  const srcOff = (pixelY * width + pixelX) * 4;
                  const wt = weights[maskY * side + maskX];
                  r += src[srcOff] * wt;
                  g += src[srcOff + 1] * wt;
                  b += src[srcOff + 2] * wt;
                }
              }
              dst[dstOff] = Math.min(255, Math.max(0, r));
              dst[dstOff + 1] = Math.min(255, Math.max(0, g));
              dst[dstOff + 2] = Math.min(255, Math.max(0, b));
              dst[dstOff + 3] = src[dstOff + 3]; // preserved aplha
            }
          }
          ctx.putImageData(output, 0, 0);
        } catch (e) {
          console.warn("CORS rules blocked image data sharpen pass.", e);
        }
      }
    };
    img.onerror = () => {
      console.warn("Could not load image to canvas");
    };
  }, [manualProductForm.imageUrl, canvasFilterBrightness, canvasFilterContrast, canvasFilterSaturation, canvasAspectRatio, canvasImageEnhanced]);

