  useEffect(() => {
    if (!modalIsDragging) return;

    const handleMouseMove = (e: MouseEvent) => {
      const container = document.getElementById("slot-story-creator-modal-container");
      if (container) {
        const rect = container.getBoundingClientRect();
        let newWidth = rect.right - e.clientX;
        if (newWidth < 220) newWidth = 220;
        if (newWidth > 500) newWidth = 500;
        setModalRightWidth(newWidth);
      }
    };

    const handleTouchMove = (e: TouchEvent) => {
      if (e.touches.length === 0) return;
      const container = document.getElementById("slot-story-creator-modal-container");
      if (container) {
        const rect = container.getBoundingClientRect();
        let newWidth = rect.right - e.touches[0].clientX;
        if (newWidth < 220) newWidth = 220;
        if (newWidth > 500) newWidth = 500;
        setModalRightWidth(newWidth);
      }
    };

    const handleEndDrag = () => {
      setModalIsDragging(false);
    };

    document.addEventListener("mousemove", handleMouseMove);
    document.addEventListener("mouseup", handleEndDrag);
    document.addEventListener("touchmove", handleTouchMove, { passive: true });
    document.addEventListener("touchend", handleEndDrag);

    return () => {
      document.removeEventListener("mousemove", handleMouseMove);
      document.removeEventListener("mouseup", handleEndDrag);
      document.removeEventListener("touchmove", handleTouchMove);
      document.removeEventListener("touchend", handleEndDrag);
    };
  }, [modalIsDragging]);

