  const handleProfilePicChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        if (typeof reader.result === "string") {
          handleUpdateStoreProfile({ logo: reader.result });
          setMerchantFeedbackMessage("Profile picture updated!");
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleCoverPicChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    const readFilesPromises = Array.from(files).map((file: File) => {
      return new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onloadend = () => {
          if (typeof reader.result === "string") {
            resolve(reader.result);
          } else {
            resolve("");
          }
        };
        reader.readAsDataURL(file);
      });
    });

    Promise.all(readFilesPromises).then((results) => {
      const validResults = results.filter((res) => res !== "");
      if (validResults.length > 0) {
        const currentBanners = myStore.banners || (myStore.banner ? [myStore.banner] : []);
        const nextBanners = [...currentBanners, ...validResults];
        
        handleUpdateStoreProfile({
          banner: nextBanners[0],
          banners: nextBanners
        });
        setCurrentMerchantBannerIdx(nextBanners.length - 1); // transition to the newly added slide
        setMerchantFeedbackMessage(`Successfully uploaded ${validResults.length} cover picture(s) to your slideshow!`);
      }
    });
  };

