  const handleBulkGenerateAltText = async () => {
    if (!checkPermission("manageProducts", "Generate Alt-Text in Bulk", "Manage Products")) return;
    if (selectedProductIds.length === 0) return;

    setIsAltTextBulkProcessing(true);
    setAltTextBulkProgress({ current: 0, total: selectedProductIds.length });

    const targetProducts = myStore.products.filter(p => selectedProductIds.includes(p.id));
    let successCount = 0;

    for (let i = 0; i < targetProducts.length; i++) {
      const prod = targetProducts[i];
      setAltTextBulkProgress({ current: i, total: targetProducts.length });
      
      try {
        const response = await fetch("/api/generate-alt-text", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            imageUrl: prod.imageUrl,
            model: selectedAltTextModel,
            productName: prod.name,
            category: prod.category
          }),
        });

        if (response.ok) {
          const data = await response.json();
          if (data.success) {
            setStores((prevStores) =>
              prevStores.map((s) => {
                return {
                  ...s,
                  products: s.products.map((p) =>
                    p.id === prod.id
                      ? {
                          ...p,
                          altText: data.altText,
                          detailedDescription: data.detailedDescription,
                          altTextModel: data.modelUsed,
                        }
                      : p
                  ),
                };
              })
            );
            successCount++;
          }
        }
      } catch (err) {
        console.error(`Failed to generate alt-text for product ${prod.id}:`, err);
      }
    }

    setAltTextBulkProgress({ current: targetProducts.length, total: targetProducts.length });
    setMerchantFeedbackMessage(`Successfully generated Alt-Text for ${successCount} product(s) using ${selectedAltTextModel}!`);
    setSelectedProductIds([]);
    setIsAltTextBulkProcessing(false);
  };

  const handleSingleProductGenerateAltText = async (prodId: string) => {
    if (!checkPermission("manageProducts", "Generate Alt-Text", "Manage Products")) return;
    const prod = myStore.products.find(p => p.id === prodId);
    if (!prod) return;

    setLoadingAltTextProductId(prodId);
    try {
      const response = await fetch("/api/generate-alt-text", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          imageUrl: prod.imageUrl,
          model: selectedAltTextModel,
          productName: prod.name,
          category: prod.category
        }),
      });

      if (response.ok) {
        const data = await response.json();
        if (data.success) {
          setStores((prevStores) =>
            prevStores.map((s) => {
              if (s.id === myStore.id) {
                return {
                  ...s,
                  products: s.products.map((p) =>
                    p.id === prodId
                      ? {
                          ...p,
                          altText: data.altText,
                          detailedDescription: data.detailedDescription,
                          altTextModel: data.modelUsed,
                        }
                      : p
                  ),
                };
              }
              return s;
            })
          );
          setMerchantFeedbackMessage(`Successfully generated Alt-Text for "${prod.name}" using ${selectedAltTextModel}!`);
        } else {
          setMerchantFeedbackMessage(`Failed to generate Alt-Text: ${data.error || "Unknown error"}`);
        }
      } else {
        setMerchantFeedbackMessage("API error. Vision analysis failed.");
      }
    } catch (err) {
      console.error(`Failed to generate alt-text for product ${prodId}:`, err);
      setMerchantFeedbackMessage("Network error during Alt-Text generation.");
    } finally {
      setLoadingAltTextProductId(null);
    }
  };

  const handleBatchGenerateMissingAltText = async () => {
    if (!checkPermission("manageProducts", "Generate Alt-Text in Bulk", "Manage Products")) return;
    
    const missingProducts = myStore.products.filter(p => !p.altText);
    if (missingProducts.length === 0) {
      setMerchantFeedbackMessage("All products already have Alt-Text! No batch scanning needed.");
      return;
    }

    setIsBatchProcessingMissing(true);
    setBatchMissingProgress({ current: 0, total: missingProducts.length });
    let successCount = 0;

    for (let i = 0; i < missingProducts.length; i++) {
      const prod = missingProducts[i];
      setBatchMissingProgress({ current: i, total: missingProducts.length });
      
      try {
        const response = await fetch("/api/generate-alt-text", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            imageUrl: prod.imageUrl,
            model: selectedAltTextModel,
            productName: prod.name,
            category: prod.category
          }),
        });

        if (response.ok) {
          const data = await response.json();
          if (data.success) {
            setStores((prevStores) =>
              prevStores.map((s) => {
                if (s.id === myStore.id) {
                  return {
                    ...s,
                    products: s.products.map((p) =>
                      p.id === prod.id
                        ? {
                            ...p,
                            altText: data.altText,
                            detailedDescription: data.detailedDescription,
                            altTextModel: data.modelUsed,
                          }
                        : p
                    ),
                  };
                }
                return s;
              })
            );
            successCount++;
          }
        }
      } catch (err) {
        console.error(`Failed to generate alt-text for product ${prod.id}:`, err);
      }
    }

    setBatchMissingProgress({ current: missingProducts.length, total: missingProducts.length });
    setMerchantFeedbackMessage(`Accessibility Batch Scan Complete: Successfully resolved Alt-Text for ${successCount} product(s)!`);
    setIsBatchProcessingMissing(false);
  };

